<?php
require_once __DIR__.'/../includes/bootstrap.php';
$user=require_login('provider');
$stmt=db()->prepare('SELECT b.*,tr.request_number,tr.destination,tr.start_date,tr.end_date,u.first_name,u.last_name FROM bookings b INNER JOIN providers p ON p.id=b.provider_id INNER JOIN users u ON u.id=b.user_id LEFT JOIN trip_requests tr ON tr.id=b.trip_request_id WHERE p.user_id=? ORDER BY b.created_at DESC');
$stmt->bind_param('i',$user['id']);$stmt->execute();$bookings=$stmt->get_result();
$page_title='Provider Bookings';require __DIR__.'/../includes/header.php';
?><div class="container py-5"><div class="mb-4"><h1 class="h3 mb-1">Bookings</h1><p class="text-secondary mb-0">Manage travelers who selected your offers.</p></div><div class="card"><div class="card-body"><?php if($bookings->num_rows===0):?><p class="text-secondary mb-0">No bookings yet.</p><?php else:?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Booking</th><th>Traveler</th><th>Trip</th><th>Amount</th><th>Payment</th><th>Status</th></tr></thead><tbody><?php while($b=$bookings->fetch_assoc()):?><tr><td><?=e($b['booking_number'])?></td><td><?=e(trim($b['first_name'].' '.$b['last_name']))?></td><td><?=e($b['destination']??'')?><br><small class="text-secondary"><?=e($b['start_date']??'')?> → <?=e($b['end_date']??'')?></small></td><td><?=e($b['currency'])?> <?=number_format((float)$b['total_amount'],2)?></td><td><?=e($b['payment_status'])?></td><td><span class="badge text-bg-light"><?=e($b['booking_status'])?></span></td></tr><?php endwhile;?></tbody></table></div><?php endif;?></div></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
